sys_script_include.script:
var base64Conversions = Class.create();
base64Conversions.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    decodeBase64Files: function(base64String) { //EL layer has to send us with data:image/jpeg;base64
        var mime = "application/octet-stream"; // default if unknown
        var fileExt = "bin"; // default extension

        // If Base64 has prefix like "data:application/pdf;base64,..."
        if (base64String && base64String.startsWith('data:')) {
            mime = base64String.substring(
                base64String.indexOf(":") + 1,
                base64String.indexOf(";")
            ); // "application/pdf", "image/png", "application/vnd.ms-excel"
            base64String = base64String.split(',')[1]; // strip prefix
        }

        // MIME map //add more extensions if needed
        var mimeMap = {
            "image/png": "png",
            "image/jpeg": "jpg",
            "image/jpg": "jpg",
            "image/gif": "gif",
            "application/pdf": "pdf",
            "application/vnd.ms-excel": "xls",
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": "xlsx",
            "application/msword": "doc",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document": "docx",
            "text/plain": "txt",
            "text/csv": "csv"
        };

        if (mimeMap[mime]) {
            fileExt = mimeMap[mime];
        }

        if (base64String) {
            var base64Bytes = GlideStringUtil.base64DecodeAsBytes(base64String);

            if (base64Bytes) {
                var attachment = new GlideSysAttachment();
                var fileName = 'attachment.' + fileExt;

                var attachmentSysId = attachment.write(gr, fileName, mime, base64Bytes);

                if (attachmentSysId) {
                    gs.info("Attachment created with sys_id: " + attachmentSysId + " (" + fileName + ")");
                } else {
                    gs.error("Failed to create attachment.");
                }
            } else {
                gs.error("Failed to decode Base64 string. Check its format.");
            }
        }

    },


    readnestedJSON: function() {
        try {

            var getInboundRec = new GlideRecord('incident');
            getInboundRec.get('28ed75c09747aa10a78db62de053af48');

            var getPayload = JSON.parse(getInboundRec.description);

            // Mapping Variables from ValueMap
            var accountNumber;
            var cashValue;
            var currency;
            var cusip;
            var eventId;
            var instrumentIdentifier;
            var instrumentName;
            var isin;
            var market;
            var notionalValue;
            var placeOfTrade;
            var price;
            var product;
            var quantity;
            var sedol;
            var settlementAmount;
            var settlementCurrency;
            var settlementDate;
            var sourceRecordId;
            var tradeDate;
            var tradeIdentifier;

            // Check if Resources[] exists (multi-set)
            if (getPayload.PAYLOAD.Resources && Array.isArray(getPayload.PAYLOAD.Resources)) {

                gs.info("----- Processing Multiple Payload Attributes -----");
                var resources = getPayload.PAYLOAD.Resources;

                for (var r = 0; r < resources.length; r++) {
                    var resource = resources[r];
                    gs.info("----- Processing Resource " + (r + 1) + " (id: " + resource.id + ") -----");

                    if (resource.attributes && resource.attributes.meta && resource.attributes.values) {
                        var metaArr = resource.attributes.meta;
                        var valuesObj = resource.attributes.values;

                        var valueMap = {};
                        for (var i = 0; i < metaArr.length; i++) {
                            var keyName = metaArr[i].key;

                            if (valuesObj[keyName] && valuesObj[keyName].length > 0) {
                                var val = valuesObj[keyName][0].value;
                                valueMap[keyName] = val;
                                gs.info("Resource " + (r + 1) + " | Key: " + keyName + " | Value: " + val);
                            }
                        }
                        accountNumber = valueMap.accountNumber;
                        cashValue = valueMap.cashValue;
                        currency = valueMap.currency;
                        cusip = valueMap.cusip;
                        eventId = valueMap.eventId;
                        instrumentIdentifier = valueMap.instrumentIdentifier;
                        instrumentName = valueMap.instrumentName;
                        isin = valueMap.isin;
                        market = valueMap.market;
                        notionalValue = valueMap.notionalValue;
                        placeOfTrade = valueMap.placeOfTrade;
                        price = valueMap.price;
                        product = valueMap.product;
                        quantity = valueMap.quantity;
                        sedol = valueMap.sedol;
                        settlementAmount = valueMap.settlementAmount;
                        settlementCurrency = valueMap.settlementCurrency;
                        settlementDate = valueMap.settlementDate;
                        sourceRecordId = valueMap.sourceRecordId;
                        tradeDate = valueMap.tradeDate;
                        tradeIdentifier = valueMap.tradeIdentifier;

                        gs.info('AccountNumber ' + accountNumber);
                        gs.info('cashValue ' + cashValue);


                        // Example access
                        gs.info("Resource " + (r + 1) + " accountNumber: " + valueMap.accountNumber);
                    } else {
                        gs.info("Resource " + (r + 1) + " has no attributes");
                    }
                }

            }
            // Else handle single-set (direct attributes)
            else if (getPayload.PAYLOAD.attributes && getPayload.PAYLOAD.attributes.meta && getPayload.PAYLOAD.attributes.values) {
                gs.info("----- Processing Single Payload Attributes -----");

                var metaArrSingle = getPayload.PAYLOAD.attributes.meta;
                var valuesObjSingle = getPayload.PAYLOAD.attributes.values;

                var valueMapSingle = {};
                for (var j = 0; j < metaArrSingle.length; j++) {
                    var keyNameSingle = metaArrSingle[j].key;

                    if (valuesObjSingle[keyNameSingle] && valuesObjSingle[keyNameSingle].length > 0) {
                        var valSingle = valuesObjSingle[keyNameSingle][0].value;
                        valueMapSingle[keyNameSingle] = valSingle;
                        // gs.info("Single Payload | Key: " + keyNameSingle + " | Value: " + valSingle);
                    }

                }

                accountNumber = valueMapSingle.accountNumber;
                cashValue = valueMapSingle.cashValue;
                currency = valueMapSingle.currency;
                cusip = valueMapSingle.cusip;
                eventId = valueMapSingle.eventId;
                instrumentIdentifier = valueMapSingle.instrumentIdentifier;
                instrumentName = valueMapSingle.instrumentName;
                isin = valueMapSingle.isin;
                market = valueMapSingle.market;
                notionalValue = valueMapSingle.notionalValue;
                placeOfTrade = valueMapSingle.placeOfTrade;
                price = valueMapSingle.price;
                product = valueMapSingle.product;
                quantity = valueMapSingle.quantity;
                sedol = valueMapSingle.sedol;
                settlementAmount = valueMapSingle.settlementAmount;
                settlementCurrency = valueMapSingle.settlementCurrency;
                settlementDate = valueMapSingle.settlementDate;
                sourceRecordId = valueMapSingle.sourceRecordId;
                tradeDate = valueMapSingle.tradeDate;
                tradeIdentifier = valueMapSingle.tradeIdentifier;

                gs.info('AccountNumber ' + accountNumber);
                gs.info('cashValue ' + cashValue);


            } else {
                gs.info("No attributes found in payload");
            }


        } catch (ex) {
            gs.info('Error From MSS Taskize Bubble Create/Update: ' + ex);
        }
    },
    type: 'base64Conversions'
});
